using System.Reflection;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;
using MA = Mono.Cecil.MethodAttributes;
using TA = Mono.Cecil.TypeAttributes;

static class BodyShapeFixture
{
    public static async Task Run(string auditPath, string directory)
    {
        Assembly tool = Assembly.LoadFrom(Path.GetFullPath(auditPath));
        MethodInfo inspect = tool.GetType("NativeHookBodyInspection", true)!.GetMethod("Classify", BindingFlags.NonPublic | BindingFlags.Static)!;
        using var assembly = AssemblyDefinition.CreateAssembly(new AssemblyNameDefinition("BodyShapeFixture", new Version(1,0)), "BodyShapeFixture", ModuleKind.Dll);
        ModuleDefinition m = assembly.MainModule;
        var type = new TypeDefinition("Fixtures", "Shapes", TA.Public, m.TypeSystem.Object);m.Types.Add(type);
        var checks = new List<object>();
        MethodDefinition Make(string name, TypeReference returns, bool isStatic=false)
        {
            var method=new MethodDefinition(name, MA.Public | (isStatic?MA.Static:0), returns);type.Methods.Add(method);return method;
        }
        void Expect(MethodDefinition method,string expected)
        {
            string actual=(string)inspect.Invoke(null,[method])!;
            if(actual!=expected)throw new InvalidOperationException($"{method.Name}: {actual} != {expected}");
            checks.Add(new {method=method.Name,expected,actual});
        }
        void Emit(MethodDefinition method, params Instruction[] instructions)
        {foreach(var i in instructions)method.Body.Instructions.Add(i);}
        var empty=Make("EmptyVoid",m.TypeSystem.Void);Emit(empty,Instruction.Create(OpCodes.Ret));Expect(empty,"empty-void");
        var boolean=Make("BooleanConstant",m.TypeSystem.Boolean);Emit(boolean,Instruction.Create(OpCodes.Ldc_I4_1),Instruction.Create(OpCodes.Ret));Expect(boolean,"return-int32-constant");
        var integer=Make("IntegerConstant",m.TypeSystem.Int32);Emit(integer,Instruction.Create(OpCodes.Ldc_I4_M1),Instruction.Create(OpCodes.Ret));Expect(integer,"return-int32-constant");
        var nullRef=Make("ReferenceNull",m.TypeSystem.Object);Emit(nullRef,Instruction.Create(OpCodes.Ldnull),Instruction.Create(OpCodes.Ret));Expect(nullRef,"return-null");
        var arg=Make("InstanceArgument",m.TypeSystem.Object);arg.Parameters.Add(new ParameterDefinition(m.TypeSystem.Object));Emit(arg,Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Ret));Expect(arg,"return-argument");
        var stat=Make("StaticArgument",m.TypeSystem.Int32,true);stat.Parameters.Add(new ParameterDefinition(m.TypeSystem.Int32));Emit(stat,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Ret));Expect(stat,"return-argument");
        foreach(bool shortForm in new[]{false,true})
        {
            var wide=Make(shortForm?"IndexedShortArgument":"IndexedArgument",m.TypeSystem.Int32);
            for(int i=0;i<5;i++)wide.Parameters.Add(new ParameterDefinition(m.TypeSystem.Int32));
            Emit(wide,Instruction.Create(shortForm?OpCodes.Ldarg_S:OpCodes.Ldarg,wide.Parameters[4]),Instruction.Create(OpCodes.Ret));Expect(wide,"return-argument");
        }
        var receiver=Make("ReceiverIsNotParameter",type);Emit(receiver,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Ret));Expect(receiver,"unclassified");
        var byref=Make("ByrefAlias",new ByReferenceType(m.TypeSystem.Int32));byref.Parameters.Add(new ParameterDefinition(byref.ReturnType));Emit(byref,Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Ret));Expect(byref,"unclassified");
        var scopeA=new AssemblyNameReference("ScopeA",new Version(1,0));var scopeB=new AssemblyNameReference("ScopeB",new Version(1,0));m.AssemblyReferences.Add(scopeA);m.AssemblyReferences.Add(scopeB);
        TypeReference A()=>new("Same","Model",m,scopeA);TypeReference B()=>new("Same","Model",m,scopeB);
        var scopes=Make("SameNameDifferentScope",A());scopes.Parameters.Add(new ParameterDefinition(B()));Emit(scopes,Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Ret));Expect(scopes,"unclassified");
        var container=new TypeReference("Same","Container`1",m,scopeA);
        var ga=new GenericInstanceType(container);ga.GenericArguments.Add(A());var gb=new GenericInstanceType(container);gb.GenericArguments.Add(B());
        var genericScope=Make("NestedGenericArgumentScope",ga);genericScope.Parameters.Add(new ParameterDefinition(gb));Emit(genericScope,Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Ret));Expect(genericScope,"unclassified");
        var unresolved=Make("UnresolvedGeneric",m.TypeSystem.Object);var gp=new GenericParameter("T",unresolved);unresolved.GenericParameters.Add(gp);unresolved.ReturnType=gp;unresolved.Parameters.Add(new ParameterDefinition(gp));Emit(unresolved,Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Ret));Expect(unresolved,"unclassified");
        var field=new FieldDefinition("State",Mono.Cecil.FieldAttributes.Static|Mono.Cecil.FieldAttributes.Public,m.TypeSystem.Int32);type.Fields.Add(field);
        var write=Make("WriteBeforeReturn",m.TypeSystem.Boolean,true);Emit(write,Instruction.Create(OpCodes.Ldc_I4_1),Instruction.Create(OpCodes.Stsfld,field),Instruction.Create(OpCodes.Ldc_I4_0),Instruction.Create(OpCodes.Ret));Expect(write,"unclassified");
        var getter=Make("SideEffectingStaticGetter",m.TypeSystem.Object,true);Emit(getter,Instruction.Create(OpCodes.Ldc_I4_1),Instruction.Create(OpCodes.Stsfld,field),Instruction.Create(OpCodes.Ldnull),Instruction.Create(OpCodes.Ret));
        var caller=Make("UnresolvedCallIsNotCertified",m.TypeSystem.Object);Emit(caller,Instruction.Create(OpCodes.Call,getter),Instruction.Create(OpCodes.Ret));Expect(caller,"return-parameterless-static-call");
        var instanceGetter=Make("InstanceGetter",m.TypeSystem.Object);Emit(instanceGetter,Instruction.Create(OpCodes.Ldnull),Instruction.Create(OpCodes.Ret));
        var invalidCall=Make("CallRequiresReceiver",m.TypeSystem.Object);Emit(invalidCall,Instruction.Create(OpCodes.Call,instanceGetter),Instruction.Create(OpCodes.Ret));Expect(invalidCall,"unclassified");
        var wrongConstant=Make("WrongConstantReturnType",m.TypeSystem.Object);Emit(wrongConstant,Instruction.Create(OpCodes.Ldc_I4_0),Instruction.Create(OpCodes.Ret));Expect(wrongConstant,"unclassified");
        var local=Make("LocalState",m.TypeSystem.Int32);local.Body.Variables.Add(new VariableDefinition(m.TypeSystem.Int32));Emit(local,Instruction.Create(OpCodes.Ldc_I4_0),Instruction.Create(OpCodes.Ret));Expect(local,"unclassified");
        var handler=Make("ExceptionRegion",m.TypeSystem.Void);Emit(handler,Instruction.Create(OpCodes.Ret));handler.Body.ExceptionHandlers.Add(new ExceptionHandler(ExceptionHandlerType.Finally));Expect(handler,"unclassified");
        var branch=Make("Branch",m.TypeSystem.Boolean);var ret=Instruction.Create(OpCodes.Ret);Emit(branch,Instruction.Create(OpCodes.Ldc_I4_1),Instruction.Create(OpCodes.Br_S,ret),ret);Expect(branch,"unclassified");
        var noBody=Make("MissingBody",m.TypeSystem.Void);noBody.Attributes|=MA.Abstract|MA.Virtual;Expect(noBody,"unclassified");
        File.WriteAllText(Path.Combine(directory,"body-shape-checks.json"),JsonSerializer.Serialize(checks,new JsonSerializerOptions{WriteIndented=true}));
        await CheckRawBodies(auditPath,directory);
        Console.WriteLine($"HOOK_BODY_METADATA_BOUNDARIES_OK shapes={checks.Count} raw=5");
    }

    private static async Task CheckRawBodies(string auditPath,string directory)
    {
        using var a=AssemblyDefinition.CreateAssembly(new AssemblyNameDefinition("RawBodyFixture",new Version(1,0)),"RawBodyFixture.dll",ModuleKind.Dll);var m=a.MainModule;
        var root=new TypeDefinition("MegaCrit.Sts2.Core.Models","AbstractModel",TA.Public,m.TypeSystem.Object);m.Types.Add(root);
        var first=new MethodDefinition("Twin",MA.Public|MA.Virtual|MA.NewSlot,m.TypeSystem.Int32);root.Methods.Add(first);first.Body.Instructions.Add(Instruction.Create(OpCodes.Ldc_I4_0));first.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
        var second=new MethodDefinition("Twin",MA.Public|MA.Virtual|MA.NewSlot,m.TypeSystem.Int32);second.GenericParameters.Add(new GenericParameter("T",second));root.Methods.Add(second);second.Body.Instructions.Add(Instruction.Create(OpCodes.Ldc_I4_1));second.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
        var hook=new TypeDefinition("MegaCrit.Sts2.Core.Hooks","Hook",TA.Public,m.TypeSystem.Object);m.Types.Add(hook);var entry=new MethodDefinition("Probe",MA.Public|MA.Static,m.TypeSystem.Void);entry.Parameters.Add(new ParameterDefinition(root));hook.Methods.Add(entry);
        entry.Body.Instructions.Add(Instruction.Create(OpCodes.Ldarg_0));entry.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt,first));entry.Body.Instructions.Add(Instruction.Create(OpCodes.Pop));entry.Body.Instructions.Add(Instruction.Create(OpCodes.Ldarg_0));var instance=new GenericInstanceMethod(second);instance.GenericArguments.Add(m.TypeSystem.Int32);entry.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt,instance));entry.Body.Instructions.Add(Instruction.Create(OpCodes.Pop));entry.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
        string input=Path.Combine(directory,"raw-body-fixture.dll"),output=Path.Combine(directory,"raw-body-fixture-audit.json");a.Write(input);
        var info=new ProcessStartInfo("dotnet"){RedirectStandardOutput=true,RedirectStandardError=true};info.ArgumentList.Add(Path.GetFullPath(auditPath));info.ArgumentList.Add(input);info.ArgumentList.Add(output);using var process=Process.Start(info)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();if(process.ExitCode!=0)throw new InvalidOperationException(await stdout+await stderr);
        using var d=JsonDocument.Parse(File.ReadAllText(output));var bodies=d.RootElement.GetProperty("nativeHookModelBodies").EnumerateArray().ToArray();
        if(bodies.Length!=2)throw new InvalidOperationException("Text-colliding hook definitions were lost.");
        if(bodies.Select(b=>b.GetProperty("DefinitionToken").GetInt32()).Distinct().Count()!=2)throw new InvalidOperationException("Definition tokens not retained.");
        if(bodies.Any(b=>b.GetProperty("ModuleMvid").GetGuid()!=m.Mvid))throw new InvalidOperationException("Wrong body module identity.");
        string zero=Convert.ToHexString(SHA256.HashData(new byte[]{0x16,0x2a})).ToLowerInvariant(),one=Convert.ToHexString(SHA256.HashData(new byte[]{0x17,0x2a})).ToLowerInvariant();
        if(!bodies.Select(b=>b.GetProperty("IlSha256").GetString()).ToHashSet().SetEquals(new[]{zero,one}))throw new InvalidOperationException("Raw IL digest mismatch.");
        if(bodies.Any(b=>b.GetProperty("Instructions").GetArrayLength()!=2))throw new InvalidOperationException("Instruction evidence lost.");
    }
}

using System.Diagnostics;
using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;

static class EventFixture
{
    public static async Task Run(string audit, string directory)
    {
        using AssemblyDefinition assembly = AssemblyDefinition.CreateAssembly(
            new AssemblyNameDefinition("EventMetadataFixture", new Version(1, 0)),
            "EventMetadataFixture.dll", ModuleKind.Dll);
        ModuleDefinition module = assembly.MainModule;
        TypeReference action = module.ImportReference(typeof(Action));
        var card = new TypeDefinition("MegaCrit.Sts2.Core.Models", "CardModel",
            TypeAttributes.Public | TypeAttributes.Class, module.TypeSystem.Object);
        module.Types.Add(card);
        var add = new MethodDefinition("add_Played", MethodAttributes.Public | MethodAttributes.SpecialName,
            module.TypeSystem.Void);
        add.Parameters.Add(new ParameterDefinition(action));
        add.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));card.Methods.Add(add);
        card.Events.Add(new EventDefinition("Played", EventAttributes.None, action) { AddMethod = add });
        var calls = new TypeDefinition("Fixture", "Calls", TypeAttributes.Public | TypeAttributes.Class,
            module.TypeSystem.Object);module.Types.Add(calls);
        var real = new AssemblyNameReference("ActualGame", new Version(1, 0));
        var wrong = new AssemblyNameReference("OtherGame", new Version(1, 0));
        var next = new AssemblyNameReference("ActualGame", new Version(2, 0));
        module.AssemblyReferences.Add(real);module.AssemblyReferences.Add(wrong);module.AssemblyReferences.Add(next);
        MethodReference External(string ns, string type, string method, IMetadataScope scope, bool instance = true)
        {
            var reference = new MethodReference(method, module.TypeSystem.Void,
                new TypeReference(ns, type, module, scope)) { HasThis = instance };
            reference.Parameters.Add(new ParameterDefinition(action));return reference;
        }
        void Edge(string name, MethodReference target, bool delegateOnly = false)
        {
            var caller = new MethodDefinition(name, MethodAttributes.Public | MethodAttributes.Static,
                module.TypeSystem.Void);calls.Methods.Add(caller);
            if (delegateOnly) {
                caller.Body.Instructions.Add(Instruction.Create(OpCodes.Ldftn, target));
                caller.Body.Instructions.Add(Instruction.Create(OpCodes.Pop));
            } else {
                if (target.HasThis) caller.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));
                caller.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));
                caller.Body.Instructions.Add(Instruction.Create(OpCodes.Call, target));
            }
            caller.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
        }
        const string ns = "MegaCrit.Sts2.Core.Entities.Cards";
        Edge("LocalEvent", add);
        Edge("ExternalAdd", External(ns, "CardPile", "add_ContentsChanged", real));
        Edge("ExternalRemove", External(ns, "CardPile", "remove_ContentsChanged", real));
        Edge("WrongAssembly", External(ns, "CardPile", "add_ContentsChanged", wrong));
        Edge("OtherVersion", External(ns, "CardPile", "add_ContentsChanged", next));
        Edge("DifferentShape", External(ns, "CardPile", "add_ContentsChanged", real, false));
        Edge("DelegateOnly", External(ns, "CardPile", "add_CardRemoved", real), true);
        Edge("NotDefinedAsEvent", External(ns, "CardPile", "add_NotAnEvent", real));
        Edge("OrdinaryName", External(ns, "CardPile", "NotifyContentsChanged", real));
        Edge("OtherType", External("Other", "CardPile", "add_ContentsChanged", real));
        string dll = Path.Combine(directory, "event-fixture.dll");assembly.Write(dll);
        string output = Path.Combine(directory, "event-audit.json");
        var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true };
        start.ArgumentList.Add(Path.GetFullPath(audit));start.ArgumentList.Add(dll);start.ArgumentList.Add(output);
        using Process process = Process.Start(start) ?? throw new InvalidOperationException("Failed to start scan.");
        Task<string> stdout = process.StandardOutput.ReadToEndAsync(), stderr = process.StandardError.ReadToEndAsync();
        await process.WaitForExitAsync();
        if (process.ExitCode != 0) throw new InvalidOperationException(await stdout + await stderr);
        using JsonDocument result = JsonDocument.Parse(File.ReadAllText(output));
        JsonElement root = result.RootElement;
        JsonElement[] rows = root.GetProperty("cardStateEventAccessorCandidates").EnumerateArray().ToArray();
        var checks = new List<string>();
        void Check(string name, bool pass) {
            if (!pass) throw new InvalidOperationException(name);checks.Add(name);
        }
        JsonElement Row(string name) => rows.Single(x => x.GetProperty("Reference").GetProperty("Caller")
            .GetString()!.Contains("::" + name + "(", StringComparison.Ordinal));
        Check("local-event-list-stays-local", root.GetProperty("cardStateEventDefinitions").GetArrayLength() == 1
            && root.GetProperty("cardStateEventReferences").GetArrayLength() == 1 && rows.Length == 8);
        Check("external-add-and-remove-retained", Row("ExternalAdd").GetProperty("AccessorName").GetString() == "add_ContentsChanged"
            && Row("ExternalRemove").GetProperty("AccessorName").GetString() == "remove_ContentsChanged");
        Check("assembly-and-version-homonyms-distinguished", new[] { "ExternalAdd", "WrongAssembly", "OtherVersion" }
            .Select(name => Row(name).GetProperty("ScopeIdentity").GetString()).Distinct().Count() == 3
            && new[] { "ExternalAdd", "WrongAssembly", "OtherVersion" }.Select(name => Row(name)
                .GetProperty("Reference").GetProperty("Target").GetString()).Distinct().Count() == 1);
        Check("instance-shape-retained", Row("ExternalAdd").GetProperty("HasThis").GetBoolean()
            && !Row("DifferentShape").GetProperty("HasThis").GetBoolean()
            && Row("DifferentShape").GetProperty("ParameterTypeIdentities").GetArrayLength() == 1);
        Check("delegate-creation-is-not-execution", Row("DelegateOnly").GetProperty("Reference")
            .GetProperty("Kind").GetString() == "ldftn");
        Check("unknown-name-never-certified-and-nonaccessors-excluded", rows.All(x => x
            .GetProperty("DefinitionResolution").GetString() == "not-resolved")
            && Row("NotDefinedAsEvent").GetProperty("AccessorName").GetString() == "add_NotAnEvent"
            && !rows.Any(x => x.GetProperty("Reference").GetProperty("Caller").GetString()!
                .Contains("::OrdinaryName(", StringComparison.Ordinal)));
        Check("caller-and-operand-tokens-preserved", rows.All(x => x.GetProperty("Reference")
            .GetProperty("CallerDefinitionToken").GetInt32() != 0
            && x.GetProperty("Reference").GetProperty("OperandMetadataToken").GetInt32() != 0)
            && rows.Select(x => x.GetProperty("Reference").GetProperty("CallerDefinitionToken").GetInt32())
                .Distinct().Count() == rows.Length);
        File.WriteAllText(Path.Combine(directory, "event-result.json"), JsonSerializer.Serialize(new {
            passed = checks.Count, checks, nativeExecution = false, scannerOutput = await stdout,
            scannerError = await stderr }, new JsonSerializerOptions { WriteIndented = true }) + "\n");
        Console.WriteLine($"EVENT_METADATA_BOUNDARIES_OK cases={checks.Count}");
    }
}

using System.Diagnostics;
using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;

if (args.Length != 2) throw new ArgumentException("Usage: fixture audit.dll output-directory");
string directory = Path.GetFullPath(args[1]);
Directory.CreateDirectory(directory);
using AssemblyDefinition assembly = AssemblyDefinition.CreateAssembly(
    new AssemblyNameDefinition("SlotMetadataFixture", new Version(1, 0)), "SlotMetadataFixture.dll", ModuleKind.Dll);
ModuleDefinition module = assembly.MainModule;
const string ns = "MegaCrit.Sts2.Core.Models";
TypeDefinition root = AddType(ns, "AbstractModel", module.TypeSystem.Object);
MethodDefinition rootDo = AddMethod(root, "Do", module.TypeSystem.Void, newSlot: true);
MethodDefinition rootGet = AddMethod(root, "GetValue", module.TypeSystem.Object, newSlot: true);
MethodDefinition rootOther = AddMethod(root, "Other", module.TypeSystem.Void, newSlot: true);
TypeDefinition middle = AddType(ns, "Middle", root);
MethodDefinition middleDo = AddMethod(middle, "Do", module.TypeSystem.Void, newSlot: false);
TypeDefinition leaf = AddType(ns, "Leaf", middle);
MethodDefinition leafDo = AddMethod(leaf, "Do", module.TypeSystem.Void, newSlot: false);
MethodDefinition leafOverload = AddMethod(leaf, "Do", module.TypeSystem.Void, newSlot: true);
leafOverload.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, module.TypeSystem.Int32));
TypeDefinition newLeaf = AddType(ns, "NewLeaf", middle);
MethodDefinition hiding = AddMethod(newLeaf, "Do", module.TypeSystem.Void, newSlot: true);

// The external parent has exactly the same FullName as the local root. The
// scanner must preserve its different assembly scope rather than bind locally.
var externalAssembly = new AssemblyNameReference("ForeignModels", new Version(1, 0));
module.AssemblyReferences.Add(externalAssembly);
var externalParent = new TypeReference(ns, "AbstractModel", module, externalAssembly);
TypeDefinition externalLeaf = AddType(ns, "ExternalLeaf", externalParent);
MethodDefinition externalDo = AddMethod(externalLeaf, "Do", module.TypeSystem.Void, newSlot: false);
TypeDefinition localValue = AddType(ns, "Value", module.TypeSystem.Object);
var externalValue = new TypeReference(ns, "Value", module, externalAssembly);
MethodDefinition rootWithValue = AddMethod(root, "WithValue", module.TypeSystem.Void, newSlot: true);
rootWithValue.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, localValue));
MethodDefinition externalParameter = AddMethod(leaf, "WithValue", module.TypeSystem.Void, newSlot: false);
externalParameter.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, externalValue));

// Covariant-looking reuse is an explicit unknown for this metadata tool.
// The closest base must not be skipped to bind an older matching return type.
TypeDefinition covariant = AddType(ns, "Covariant", root);
MethodDefinition covariantGet = AddMethod(covariant, "GetValue", module.TypeSystem.String, newSlot: false);
TypeDefinition afterCovariant = AddType(ns, "AfterCovariant", covariant);
MethodDefinition afterCovariantGet = AddMethod(afterCovariant, "GetValue", module.TypeSystem.Object, newSlot: false);
TypeDefinition explicitLeaf = AddType(ns, "ExplicitLeaf", root);
MethodDefinition renamed = AddMethod(explicitLeaf, "Renamed", module.TypeSystem.Void, newSlot: true);
renamed.Overrides.Add(rootDo);
MethodDefinition multiple = AddMethod(explicitLeaf, "Multiple", module.TypeSystem.Void, newSlot: true);
multiple.Overrides.Add(rootDo);
multiple.Overrides.Add(rootOther);

// Supply one actual Hook call edge, so same-name hiding is checked against
// the referenced root slot rather than inferred from its name.
TypeDefinition hook = AddType("MegaCrit.Sts2.Core.Hooks", "Hook", module.TypeSystem.Object);
var dispatch = new MethodDefinition("Dispatch", MethodAttributes.Public | MethodAttributes.Static, module.TypeSystem.Void);
hook.Methods.Add(dispatch);
dispatch.Parameters.Add(new ParameterDefinition("model", ParameterAttributes.None, root));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Ldarg_0));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt, rootDo));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
string dll = Path.Combine(directory, "fixture.dll");
assembly.Write(dll);
string output = Path.Combine(directory, "audit.json");
var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true };
start.ArgumentList.Add(Path.GetFullPath(args[0])); start.ArgumentList.Add(dll); start.ArgumentList.Add(output);
using Process process = Process.Start(start) ?? throw new InvalidOperationException("Could not start audit tool");
Task<string> stdout = process.StandardOutput.ReadToEndAsync();
Task<string> stderr = process.StandardError.ReadToEndAsync();
await process.WaitForExitAsync();
if (process.ExitCode != 0) throw new InvalidOperationException(await stdout + await stderr);
using JsonDocument json = JsonDocument.Parse(File.ReadAllText(output));
Dictionary<string, JsonElement> slots = json.RootElement.GetProperty("virtualModelSlots")
    .EnumerateArray().ToDictionary(slot => slot.GetProperty("Method").GetString()!);
var checks = new List<object>();
Check("inherited-chain", leafDo, "resolved-local", rootDo.FullName, true, 3);
Check("overload-new-slot", leafOverload, "resolved-local", leafOverload.FullName, false, 1);
Check("same-name-hiding", hiding, "resolved-local", hiding.FullName, false, 1);
Check("external-homonym", externalDo, "external-or-unresolved-base", externalParent.FullName, false, 1);
Check("external-parameter-homonym", externalParameter, "external-or-unresolved-base", module.TypeSystem.Object.FullName, false, 1);
Check("covariant-return", covariantGet, "covariant-or-unresolved-return", rootGet.FullName, false, 1);
Check("closest-covariant-base", afterCovariantGet, "covariant-or-unresolved-return", covariantGet.FullName, false, 1);
Check("explicit-renamed-slot", renamed, "resolved-local", rootDo.FullName, true, 2);
Check("multiple-explicit-slots", multiple, "multiple-explicit-slots", null, false, 1);
string result = JsonSerializer.Serialize(new { passed = checks.Count, checks, nativeExecution = false,
    scannerOutput = await stdout, scannerError = await stderr }, new JsonSerializerOptions { WriteIndented = true });
File.WriteAllText(Path.Combine(directory, "result.json"), result + "\n");
Console.WriteLine($"SLOT_METADATA_BOUNDARIES_OK cases={checks.Count}");


using (AssemblyDefinition ambiguityAssembly = AssemblyDefinition.CreateAssembly(
    new AssemblyNameDefinition("AmbiguityMetadataFixture", new Version(1, 0)), "AmbiguityMetadataFixture.dll", ModuleKind.Dll))
{
    ModuleDefinition am = ambiguityAssembly.MainModule;
    TypeDefinition AT(string name, TypeReference parent)
    {
        var type = new TypeDefinition(ns, name, TypeAttributes.Public | TypeAttributes.Class, parent);
        am.Types.Add(type); return type;
    }
    MethodDefinition AM(TypeDefinition type, string name, bool isNewSlot = true)
    {
        var attrs = MethodAttributes.Public | MethodAttributes.Virtual | MethodAttributes.HideBySig;
        if (isNewSlot) attrs |= MethodAttributes.NewSlot;
        var method = new MethodDefinition(name, attrs, am.TypeSystem.Void);
        type.Methods.Add(method);method.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));return method;
    }
    var ar = AT("GenericArityRoot", am.TypeSystem.Object);
    var nonGeneric = AM(ar, "Same");
    var generic = AM(ar, "Same");
    generic.GenericParameters.Add(new GenericParameter("Unused", generic));
    if (nonGeneric.FullName != generic.FullName) throw new InvalidOperationException("No display-signature collision in fixture.");
    var alias = AM(AT("ExplicitAlias", ar), "Alias");alias.Overrides.Add(nonGeneric);
    var twinOne = AT("DuplicateType", am.TypeSystem.Object);
    var twinTwo = AT("DuplicateType", am.TypeSystem.Object);
    AM(twinOne, "Do");AM(twinTwo, "Do");
    AM(AT("DerivedFromDuplicateType", twinOne), "Do", false);
    var calls = AT("CallSites", am.TypeSystem.Object);
    foreach (var (name, target) in new[] { ("CallPlain", (MethodReference)nonGeneric),
        ("CallGeneric", (MethodReference)new GenericInstanceMethod(generic)) })
    {
        if (target is GenericInstanceMethod constructed) constructed.GenericArguments.Add(am.TypeSystem.String);
        var method = new MethodDefinition(name, MethodAttributes.Public | MethodAttributes.Static, am.TypeSystem.Void);
        calls.Methods.Add(method);
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt, target));
